def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place a wrong item at the destination; recover by setting it aside only if needed, then find the target.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take the target before continuing to search other containers.'
    elif stage == 'transform' and target and verb:
        msg = 'You are carrying the ' + target + '. Use the admissible ' + verb + ' action before putting it anywhere.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the admissible put action there.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the destination with the ' + target + '. Put it in/on the ' + dest + ' now.'
    elif stage == 'find_target' and target and getv(ctx, 'world.target_found', False):
        msg = 'The requested ' + target + ' has been found. Take it instead of opening or visiting more empty places.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

