def hook(ctx, nb):
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or text(getv(ctx, 'task.task_type', ''))
    verb = nb.get('required_verb') or needverb(tt)
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    if not act or not target:
        return None
    carrying = bool(target in text(getv(ctx, 'world.inventory', '')))
    wrong = bool(dest and act.startswith('put ') and target in act and dest not in act)
    if wrong and nb.get('stage') != 'wrong_inventory':
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Keep the target and go to the requested destination instead.'}
    if verb and not nb.get('transformed') and act.startswith('put ') and target in act and not (dest and dest in act):
        return {'kind': 'block_and_prompt', 'message': 'Do not put the target down yet. First use the admissible transform action for the required ' + verb + ' step.'}
    if 'pick_two' in tt and act.startswith('take ') and target in act and nb.get('placed_count', 0) > 0:
        locs = text(getv(ctx, 'world.placed_locations', []))
        if locs and locs in act:
            return {'kind': 'block_and_prompt', 'message': 'Do not take back an item already placed for the two-object task. Find another target of the same type.'}
    return None
